                        .map(|o| {
                            matches!(
                                &o.kind,
                                InodeKind::Folder {
                                    children_loaded: true,
                                    ..
                                }
                            )
                        })
                        .unwrap_or(false);
                    (ch, loaded)
                } else if existing_ino.is_some() {
                    // Display-name fallback: identity changed — clear loaded state (D-11).
                    log::info!(
                        "Folder '{}': stable-ID mismatch on fallback match, clearing loaded state (D-11)",
                        folder.name
                    );
                    (Some(vec![]), false)
                } else {
                    (Some(vec![]), false)
                };

                let attr = FileAttrs {
                    ino,
                    size: 0,
                    blocks: 0,
                    atime: modified,
                    mtime: modified,
                    ctime: modified,

